import "server-only";
import fs from "node:fs/promises";
import path from "node:path";
import { z } from "zod";
import { env } from "../env";
import { htmlToText, safeFetch } from "./net";
import { runSandboxed } from "./sandbox";
import type { ToolSpec } from "./types";

const MAX_READ_BYTES = 200_000;
const MAX_WRITE_BYTES = 1_000_000;
const MAX_LIST = 500;

export function workspaceDir(accountId: string): string {
  // Account ids are generated by us (`acct_<base64url>`), but never trust a path segment.
  if (!/^[\w-]+$/.test(accountId)) throw new Error("Invalid account id.");
  return path.join(env.dataDir, "workspaces", accountId);
}

/**
 * Resolves a model-supplied path inside the workspace. Rejects absolute paths, `..`
 * traversal, and symlinks that point outside, so file tools can never touch the host.
 */
export async function resolveInWorkspace(root: string, relative: string): Promise<string> {
  if (relative.includes("\0")) throw new Error("Invalid path.");
  if (path.isAbsolute(relative)) throw new Error("Use a path relative to the workspace, not an absolute path.");
  const target = path.resolve(root, relative);
  const rel = path.relative(root, target);
  if (rel.startsWith("..") || path.isAbsolute(rel)) throw new Error("That path is outside the workspace.");

  await fs.mkdir(root, { recursive: true });
  const realRoot = await fs.realpath(root);
  // Check the deepest existing ancestor: a symlinked directory must not lead outside.
  let probe = target;
  for (;;) {
    try {
      const real = await fs.realpath(probe);
      const relReal = path.relative(realRoot, real);
      if (relReal.startsWith("..") || path.isAbsolute(relReal)) throw new Error("That path is outside the workspace.");
      break;
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code !== "ENOENT") throw err;
      const parent = path.dirname(probe);
      if (parent === probe) break;
      probe = parent;
    }
  }
  return target;
}

const webFetch: ToolSpec = {
  name: "web_fetch",
  description:
    "Fetch a public web page or API endpoint with HTTP GET and return its content as text. HTML is reduced to readable text. Use this to read documentation, articles or JSON APIs.",
  source: "builtin",
  inputSchema: z.object({
    url: z.string().describe("Absolute http(s) URL to fetch."),
    maxChars: z.number().int().min(500).max(60_000).optional().describe("Maximum characters of content to return (default 12000)."),
  }),
  async run(args, ctx) {
    const { url, maxChars = 12_000 } = args as { url: string; maxChars?: number };
    const res = await safeFetch(url, { signal: ctx.signal });
    const contentType = res.headers["content-type"] ?? "";
    const text = /html/i.test(contentType) ? htmlToText(res.body) : res.body;
    return {
      url: res.url,
      status: res.status,
      contentType,
      content: text.slice(0, maxChars),
      truncated: res.truncated || text.length > maxChars,
    };
  },
};

const httpRequest: ToolSpec = {
  name: "http_request",
  description:
    "Make an HTTP request with any method, custom headers and a body, and return the status, headers and response body. Use for APIs that need POST/PUT/PATCH/DELETE.",
  source: "builtin",
  inputSchema: z.object({
    method: z.enum(["GET", "POST", "PUT", "PATCH", "DELETE", "HEAD"]).describe("HTTP method."),
    url: z.string().describe("Absolute http(s) URL."),
    headers: z.record(z.string(), z.string()).optional().describe("Request headers."),
    body: z.string().optional().describe("Request body as a string (JSON-encode objects yourself)."),
  }),
  async run(args, ctx) {
    const a = args as { method: string; url: string; headers?: Record<string, string>; body?: string };
    const res = await safeFetch(a.url, { method: a.method, headers: a.headers, body: a.body, signal: ctx.signal });
    return { url: res.url, status: res.status, headers: res.headers, body: res.body.slice(0, 20_000), truncated: res.truncated || res.body.length > 20_000 };
  },
};

const runJavascript: ToolSpec = {
  name: "run_javascript",
  description:
    "Run JavaScript in an isolated sandbox and return the result. Use it for calculations, data transformation and parsing. The value of the last expression is returned and console.log output is captured. There is no network, filesystem, require or import. To use await, wrap the code in an async function and call it as the last expression.",
  source: "builtin",
  inputSchema: z.object({
    code: z.string().describe("JavaScript source. The last expression's value is the result."),
  }),
  async run(args, ctx) {
    const { code } = args as { code: string };
    const out = await runSandboxed(code, { signal: ctx.signal });
    return out.ok ? { result: out.result, logs: out.logs } : { error: out.error, logs: out.logs };
  },
};

const fileRead: ToolSpec = {
  name: "file_read",
  description: "Read a UTF-8 text file from the agent workspace. Paths are relative to the workspace root.",
  source: "builtin",
  inputSchema: z.object({ path: z.string().describe("Workspace-relative path, e.g. notes/summary.md") }),
  async run(args, ctx) {
    const { path: rel } = args as { path: string };
    const target = await resolveInWorkspace(workspaceDir(ctx.accountId), rel);
    const stat = await fs.stat(target).catch(() => null);
    if (!stat) throw new Error(`No such file: ${rel}`);
    if (!stat.isFile()) throw new Error(`${rel} is not a file.`);
    const handle = await fs.open(target, "r");
    try {
      const buffer = Buffer.alloc(Math.min(stat.size, MAX_READ_BYTES));
      await handle.read(buffer, 0, buffer.length, 0);
      return { path: rel, size: stat.size, content: buffer.toString("utf8"), truncated: stat.size > MAX_READ_BYTES };
    } finally {
      await handle.close();
    }
  },
};

const fileWrite: ToolSpec = {
  name: "file_write",
  description: "Create or overwrite a UTF-8 text file in the agent workspace (or append to it). Parent folders are created as needed.",
  source: "builtin",
  inputSchema: z.object({
    path: z.string().describe("Workspace-relative path."),
    content: z.string().describe("Text to write."),
    append: z.boolean().optional().describe("Append instead of overwriting."),
  }),
  async run(args, ctx) {
    const { path: rel, content, append } = args as { path: string; content: string; append?: boolean };
    if (Buffer.byteLength(content) > MAX_WRITE_BYTES) throw new Error(`Content exceeds the ${MAX_WRITE_BYTES} byte limit.`);
    const target = await resolveInWorkspace(workspaceDir(ctx.accountId), rel);
    await fs.mkdir(path.dirname(target), { recursive: true });
    if (append) await fs.appendFile(target, content, "utf8");
    else await fs.writeFile(target, content, "utf8");
    const stat = await fs.stat(target);
    return { path: rel, bytes: stat.size, appended: append === true };
  },
};

const fileList: ToolSpec = {
  name: "file_list",
  description: "List the files and folders in the agent workspace, recursively.",
  source: "builtin",
  inputSchema: z.object({ dir: z.string().optional().describe("Workspace-relative folder (default: the workspace root).") }),
  async run(args, ctx) {
    const { dir = "." } = args as { dir?: string };
    const root = workspaceDir(ctx.accountId);
    const start = await resolveInWorkspace(root, dir);
    const entries: { path: string; type: "file" | "dir"; size?: number }[] = [];
    async function walk(current: string) {
      const items = await fs.readdir(current, { withFileTypes: true }).catch(() => []);
      for (const item of items) {
        if (entries.length >= MAX_LIST) return;
        const full = path.join(current, item.name);
        const rel = path.relative(root, full);
        // Symlinks are listed neither as files nor followed.
        if (item.isDirectory()) {
          entries.push({ path: rel, type: "dir" });
          await walk(full);
        } else if (item.isFile()) {
          entries.push({ path: rel, type: "file", size: (await fs.stat(full)).size });
        }
      }
    }
    await walk(start);
    return { entries, truncated: entries.length >= MAX_LIST };
  },
};

export const BUILTIN_SPECS: Record<string, ToolSpec> = Object.fromEntries(
  [webFetch, httpRequest, runJavascript, fileRead, fileList, fileWrite].map((t) => [t.name, t]),
);
